describe('local-models-catalog locate', () => {
  const MANIFEST = `sha256:${'5'.repeat(64)}`
  const GGUF_FILE = { path: '/w/model.gguf', title: 'model.gguf', mediaType: 'application/vnd.thyrox.gguf.v1', size: GGUF.length, sha256: GGUF_SHA256 }
